const int LED_PIN = 13;

const char* symbols[] = {
  "CHERRY",
  "LEMON",
  "STAR",
  "BELL",
  "DIAMOND"
};

int score = 0;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);

  randomSeed(analogRead(A0));

  Serial.println();
  Serial.println("=======================");
  Serial.println("   NANO SLOT MACHINE");
  Serial.println("=======================");
  Serial.println();
  Serial.println("Commands:");
  Serial.println("S = Spin");
  Serial.println("R = Reset score");
  Serial.println("H = Help");
  Serial.println();
  Serial.println("Press S to start!");
}

void loop() {
  if (Serial.available() > 0) {
    char command = Serial.read();

    if (command == 's' || command == 'S') {
      spinMachine();
    }

    if (command == 'r' || command == 'R') {
      score = 0;
      Serial.println();
      Serial.println("Score reset to 0.");
    }

    if (command == 'h' || command == 'H') {
      showHelp();
    }
  }
}

void spinMachine() {
  Serial.println();
  Serial.println("Spinning...");
  Serial.println();

  for (int i = 0; i < 6; i++) {
    int a = random(0, 5);
    int b = random(0, 5);
    int c = random(0, 5);

    Serial.print("[ ");
    Serial.print(symbols[a]);
    Serial.print(" | ");
    Serial.print(symbols[b]);
    Serial.print(" | ");
    Serial.print(symbols[c]);
    Serial.println(" ]");

    delay(150);
  }

  int slot1 = random(0, 5);
  int slot2 = random(0, 5);
  int slot3 = random(0, 5);

  Serial.println();
  Serial.println("RESULT:");
  Serial.print("[ ");
  Serial.print(symbols[slot1]);
  Serial.print(" | ");
  Serial.print(symbols[slot2]);
  Serial.print(" | ");
  Serial.print(symbols[slot3]);
  Serial.println(" ]");
  Serial.println();

  if (slot1 == slot2 && slot2 == slot3) {
    score += 10;

    Serial.println("JACKPOT! +10 points");

    flashLED(5);
  }
  else if (slot1 == slot2 || slot1 == slot3 || slot2 == slot3) {
    score += 3;

    Serial.println("MATCH! +3 points");

    flashLED(2);
  }
  else {
    Serial.println("No match.");
  }

  Serial.print("Score: ");
  Serial.println(score);

  Serial.println();
  Serial.println("Press S to spin again.");
}

void flashLED(int times) {
  for (int i = 0; i < times; i++) {
    digitalWrite(LED_PIN, HIGH);
    delay(120);

    digitalWrite(LED_PIN, LOW);
    delay(120);
  }
}

void showHelp() {
  Serial.println();
  Serial.println("===== HELP =====");
  Serial.println("S = Spin");
  Serial.println("R = Reset score");
  Serial.println("H = Show this help");
  Serial.println();
  Serial.println("3 matching symbols = 10 points");
  Serial.println("2 matching symbols = 3 points");
}
